  "content": "1|import type { DesignerBindingDefinitions, DesignerDocument } from '../../../domain/component-designer/types';
2|import type { AgentStreamEvent, ChangeSet } from '../../../shared/api/contracts/ai/agentTypes';
3|
4|const isRecord = (value: unknown): value is Record<string, unknown> => (
5|  Boolean(value) && typeof value === 'object' && !Array.isArray(value)
6|);
7|
8|export type ClientComponentLayoutApplyPayload = {
9|  document: DesignerDocument;
10|  bindingDefinitions: DesignerBindingDefinitions;
11|};
12|
13|export function isDesignerDocument(value: unknown): value is DesignerDocument {
14|  if (!isRecord(value)) {
15|    return false;
16|  }
17|  const rootNodeId = typeof value.rootNodeId === 'string' ? value.rootNodeId.trim() : '';
18|  const nodes = isRecord(value.nodes) ? value.nodes : null;
19|  if (!rootNodeId || !nodes || !isRecord(nodes[rootNodeId])) {
20|    return false;
21|  }
22|  return true;
23|}
24|
25|export function readLayoutFromComponentPatch(changeSet: ChangeSet): ClientComponentLayoutApplyPayload | null {
26|  if (changeSet.kind !== 'component_layout_patch') {
27|    return null;
28|  }
29|  const patch = isRecord(changeSet.patch) ? changeSet.patch : {};
30|  if (!isDesignerDocument(patch.document)) {
31|    return null;
32|  }
33|  const bindingDefinitions = isRecord(patch.bindingDefinitions)
34|    ? patch.bindingDefinitions as DesignerBindingDefinitions
35|    : {};
36|  return { document: patch.document, bindingDefinitions };
37|}
38|
39|export function readLayoutFromDraftComponentLayoutArgs(
40|  args: Record<string, unknown>,
41|): ClientComponentLayoutApplyPayload | null {
42|  if (!isDesignerDocument(args.document)) {
43|    return null;
44|  }
45|  const bindingDefinitions = isRecord(args.bindingDefinitions)
46|    ? args.bindingDefinitions as DesignerBindingDefinitions
47|    : {};
48|  return { document: args.document, bindingDefinitions };
49|}
50|
51|export type ClientComponentAgentApplyCollector = {
52|  ingest: (event: AgentStreamEvent) => void;
53|  layout: () => ClientComponentLayoutApplyPayload | null;
54|};
55|
56|/** Latest drafted layout from a proposal, or from draft_component_layout tool args. */
57|export function createClientComponentAgentApplyCollector(): ClientComponentAgentApplyCollector {
58|  let proposalLayout: ClientComponentLayoutApplyPayload | null = null;
59|  let draftToolLayout: ClientComponentLayoutApplyPayload | null = null;
60|
61|  return {
62|    ingest(event) {
63|      if (event.type === 'proposal') {
64|        const layouts = event.changeSets.map(readLayoutFromComponentPatch).filter(
65|          (layout): layout is ClientComponentLayoutApplyPayload => Boolean(layout),
66|        );
67|        if (layouts.length > 0) {
68|          proposalLayout = layouts[layouts.length - 1] ?? null;
69|        }
70|        return;
71|      }
72|      if (event.type === 'tool_start' && event.name === 'draft_component_layout') {
73|        const layout = readLayoutFromDraftComponentLayoutArgs(event.args);
74|        if (layout) {
75|          draftToolLayout = layout;
76|        }
77|      }
78|    },
79|    layout: () => proposalLayout ?? draftToolLayout,
80|  };
81|};
82|"
